import json
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import build_window, calendar_day_pair, utc_pair, wall_clock_pair


def validate_range(payload):
    """Return all local validation failures for one query.

    Datetimes are parsed once and compared only after conversion to UTC.  A
    naive value is made aware using the project's explicit UTC policy; the
    normalized values are included in range errors so the decision is
    inspectable by callers.
    """
    if not isinstance(payload, dict):
        return [build_rejection("query", "query must be an object", payload)]

    errors = []
    if "start_date" not in payload:
        errors.append(build_rejection("start_date", "is required", payload))

    window = None
    if "start_date" in payload:
        try:
            window = build_window({"start_date": payload["start_date"]})
        except (TypeError, ValueError, OverflowError):
            errors.append(build_rejection("start_date", "must be a valid ISO 8601 timestamp", payload))

    if "end_date" in payload:
        try:
            end = build_window({"start_date": payload["end_date"]})["start"]
        except (TypeError, ValueError, OverflowError):
            errors.append(build_rejection("end_date", "must be a valid ISO 8601 timestamp", payload))
        else:
            if window is None:
                return errors
            window["end"] = end

    # An omitted end is valid and does not form a range to compare.
    if window is None or "end" not in window:
        return errors

    start_utc, end_utc = utc_pair(window)
    start_local, end_local = wall_clock_pair(window)
    normalized = {
        "start_date": start_utc.isoformat(),
        "end_date": end_utc.isoformat(),
        "naive_timezone": DEFAULT_TIMEZONE.tzname(None),
        "naive_timezone_policy": MISSING_TZ_POLICY,
    }

    def range_error(message):
        error = build_rejection("date_range", message, payload)
        error["normalized"] = normalized
        return error

    if end_utc < start_utc:
        errors.append(range_error("end must not be before start after UTC normalization"))

    # During a fall-back overlap, the same local hour occurs under two
    # offsets.  Preserve the service's ambiguity rule even when UTC ordering
    # would otherwise make the range appear valid.
    if (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start_local > end_local
        and window["start"].utcoffset() != window["end"].utcoffset()
    ):
        errors.append(range_error("ambiguous fall-back DST range: local end is earlier than local start"))

    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    if not isinstance(payload, list):
        raise ValueError("queries file must contain an array")
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

