from __future__ import annotations

from datetime import datetime, timezone

from timezone_defaults import DEFAULT_TIMEZONE


UTC = timezone.utc


def parse_bound(value):
    if not isinstance(value, str):
        raise TypeError("timestamp must be a string")
    # ``fromisoformat`` gained support for the ISO 8601 ``Z`` suffix in
    # Python 3.11; accepting it explicitly keeps the client portable while
    # retaining the standard parser for all other ISO 8601 values.
    parsed = datetime.fromisoformat(value[:-1] + "+00:00" if value.endswith(("Z", "z")) else value)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=DEFAULT_TIMEZONE)
    return parsed


def build_window(payload):
    window = {
        "start": parse_bound(payload["start_date"]),
        "payload": payload,
    }
    if "end_date" in payload:
        window["end"] = parse_bound(payload["end_date"])
    return window


def wall_clock_pair(window):
    return (
        window["start"].replace(tzinfo=None),
        window["end"].replace(tzinfo=None),
    )


def calendar_day_pair(window):
    return (
        window["start"].date(),
        window["end"].date(),
    )


def utc_pair(window):
    return (
        window["start"].astimezone(UTC),
        window["end"].astimezone(UTC),
    )
